update t_user
set gold_coin=gold_coin + #{goldCoin}
where id = #{userId}

update t_user
set gold_coin=gold_coin - #{goldCoin}
where id = #{userId}

update t_user
set cash=cash + #{cash}
where id = #{userId}

update t_user
set cash=cash - #{cash}
where id = #{userId}

mapper.select:
select count(1)
from t_user
where parent_id = #{userId}

select count(1)
from t_user
where DATE(invitation_time) = CURDATE() and (parent_id = #{userId} or parent_id in (select id from t_user where parent_id = #{userId}));

select count(1)
from t_user
where DATE(invitation_time) = CURDATE() - INTERVAL 1 DAY and (parent_id = #{userId} or parent_id in (select id from t_user where parent_id = #{userId}));
